import{_ as t,o as s,c as a,ag as i}from"./chunks/framework.7He2WLS4.js";const g=JSON.parse('{"title":"Request Comparison","description":"Compare two HTTP requests or responses side by side with visual diff highlighting.","frontmatter":{"title":"Request Comparison","description":"Compare two HTTP requests or responses side by side with visual diff highlighting."},"headers":[],"relativePath":"features/request-comparison.md","filePath":"features/request-comparison.md","lastUpdated":1772297611000}'),n={name:"features/request-comparison.md"};function o(r,e,l,d,h,p){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="request-comparison" tabindex="-1">Request Comparison <a class="header-anchor" href="#request-comparison" aria-label="Permalink to &quot;Request Comparison&quot;">​</a></h1><p>Request Comparison lets you select any <strong>two traffic entries</strong> from the NectoProxy traffic list and view a detailed <strong>side-by-side diff</strong> of their requests and responses. Differences are visually highlighted, making it easy to identify exactly what changed between two API calls.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Comparing two HTTP transactions is a common debugging task:</p><ul><li>What changed between a working request and a failing one?</li><li>Did the API response change after a deployment?</li><li>Are two seemingly identical requests actually different?</li><li>How does the response differ between two users or environments?</li></ul><p>NectoProxy&#39;s comparison feature answers these questions by displaying a structured, highlighted diff of every aspect of the two selected entries.</p><h2 id="how-to-compare" tabindex="-1">How to Compare <a class="header-anchor" href="#how-to-compare" aria-label="Permalink to &quot;How to Compare&quot;">​</a></h2><h3 id="selecting-entries" tabindex="-1">Selecting Entries <a class="header-anchor" href="#selecting-entries" aria-label="Permalink to &quot;Selecting Entries&quot;">​</a></h3><ol><li><strong>Select the first entry</strong> in the traffic list by clicking on it</li><li><strong>Hold <code>Ctrl</code> (or <code>Cmd</code> on macOS) and click the second entry</strong> to add it to the selection</li><li>With two entries selected, click the <strong>Compare</strong> button in the toolbar, or right-click and select <strong>Compare Selected</strong></li></ol><p>The comparison view opens, showing both entries side by side with differences highlighted.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>You can compare any two entries in the traffic list, regardless of their position, session, or age. Compare a request from today with one from yesterday, or compare entries from different sessions.</p></div><h3 id="comparison-layout" tabindex="-1">Comparison Layout <a class="header-anchor" href="#comparison-layout" aria-label="Permalink to &quot;Comparison Layout&quot;">​</a></h3><p>The comparison view is divided into two columns:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+----------------------------+----------------------------+</span></span>
<span class="line"><span>|         Entry A            |         Entry B            |</span></span>
<span class="line"><span>|  (first selected entry)    |  (second selected entry)   |</span></span>
<span class="line"><span>+----------------------------+----------------------------+</span></span>
<span class="line"><span>|  Request headers           |  Request headers           |</span></span>
<span class="line"><span>|  - highlighted diffs -     |  - highlighted diffs -     |</span></span>
<span class="line"><span>+----------------------------+----------------------------+</span></span>
<span class="line"><span>|  Request body              |  Request body              |</span></span>
<span class="line"><span>|  - highlighted diffs -     |  - highlighted diffs -     |</span></span>
<span class="line"><span>+----------------------------+----------------------------+</span></span>
<span class="line"><span>|  Response headers          |  Response headers          |</span></span>
<span class="line"><span>|  - highlighted diffs -     |  - highlighted diffs -     |</span></span>
<span class="line"><span>+----------------------------+----------------------------+</span></span>
<span class="line"><span>|  Response body             |  Response body             |</span></span>
<span class="line"><span>|  - highlighted diffs -     |  - highlighted diffs -     |</span></span>
<span class="line"><span>+----------------------------+----------------------------+</span></span></code></pre></div><h2 id="what-is-compared" tabindex="-1">What is Compared <a class="header-anchor" href="#what-is-compared" aria-label="Permalink to &quot;What is Compared&quot;">​</a></h2><h3 id="request-line" tabindex="-1">Request Line <a class="header-anchor" href="#request-line" aria-label="Permalink to &quot;Request Line&quot;">​</a></h3><p>The comparison starts with the request line, showing differences in method, URL, and HTTP version:</p><div class="language-diff vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">diff</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">- GET /api/v1/users?page=1&amp;limit=10 HTTP/1.1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+ GET /api/v1/users?page=2&amp;limit=10 HTTP/1.1</span></span></code></pre></div><h3 id="header-diff" tabindex="-1">Header Diff <a class="header-anchor" href="#header-diff" aria-label="Permalink to &quot;Header Diff&quot;">​</a></h3><p>Headers are compared key by key. The diff view shows:</p><table tabindex="0"><thead><tr><th>Indicator</th><th>Meaning</th><th>Color</th></tr></thead><tbody><tr><td><strong>Added</strong></td><td>Header exists in Entry B but not in Entry A</td><td>Green</td></tr><tr><td><strong>Removed</strong></td><td>Header exists in Entry A but not in Entry B</td><td>Red</td></tr><tr><td><strong>Modified</strong></td><td>Header exists in both but values differ</td><td>Yellow/Orange</td></tr><tr><td><strong>Unchanged</strong></td><td>Header is identical in both entries</td><td>Gray (dimmed)</td></tr></tbody></table><details class="details custom-block"><summary>Example: Header Diff</summary><div class="language-diff vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">diff</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Content-Type: application/json          (unchanged)</span></span>
<span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">- Authorization: Bearer old-token-abc     (removed/modified)</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+ Authorization: Bearer new-token-xyz     (added/modified)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Accept: application/json                (unchanged)</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+ X-Request-Id: req-456                   (added)</span></span>
<span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">- X-Debug: true                           (removed)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  User-Agent: MyApp/2.0                   (unchanged)</span></span></code></pre></div></details><h3 id="body-diff" tabindex="-1">Body Diff <a class="header-anchor" href="#body-diff" aria-label="Permalink to &quot;Body Diff&quot;">​</a></h3><p>Body comparison adapts to the content type for the most meaningful diff:</p><h4 id="json-aware-diffing" tabindex="-1">JSON-Aware Diffing <a class="header-anchor" href="#json-aware-diffing" aria-label="Permalink to &quot;JSON-Aware Diffing&quot;">​</a></h4><p>For JSON bodies, NectoProxy parses and compares the JSON structure rather than performing a plain text diff. This means:</p><ul><li><strong>Key ordering</strong> does not produce false diffs (JSON objects are order-independent)</li><li><strong>Nested changes</strong> are identified precisely</li><li><strong>Added and removed keys</strong> are highlighted at the correct level</li></ul><div class="language-diff vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">diff</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &quot;name&quot;: &quot;Jane Doe&quot;,                    (unchanged)</span></span>
<span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">-   &quot;email&quot;: &quot;jane@old.com&quot;,              (modified)</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+   &quot;email&quot;: &quot;jane@new.com&quot;,              (modified)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &quot;role&quot;: &quot;admin&quot;,                       (unchanged)</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+   &quot;department&quot;: &quot;engineering&quot;,           (added)</span></span>
<span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">-   &quot;temporary&quot;: true                      (removed)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>JSON-aware diffing is automatically activated when both entries have a <code>Content-Type</code> of <code>application/json</code>. For other content types, a standard text diff is used.</p></div><h4 id="text-diff" tabindex="-1">Text Diff <a class="header-anchor" href="#text-diff" aria-label="Permalink to &quot;Text Diff&quot;">​</a></h4><p>For non-JSON text content (HTML, XML, plain text, etc.), a standard line-by-line diff is displayed:</p><div class="language-diff vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">diff</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;html&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;head&gt;</span></span>
<span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">-   &lt;title&gt;Old Page Title&lt;/title&gt;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+   &lt;title&gt;New Page Title&lt;/title&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;/head&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;body&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;h1&gt;Welcome&lt;/h1&gt;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+   &lt;p&gt;This paragraph was added.&lt;/p&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;/body&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;/html&gt;</span></span></code></pre></div><h4 id="binary-content" tabindex="-1">Binary Content <a class="header-anchor" href="#binary-content" aria-label="Permalink to &quot;Binary Content&quot;">​</a></h4><p>For binary content, the comparison shows the size difference and indicates whether the content is identical or different. A byte-level comparison is not displayed for binary data.</p><h3 id="response-status" tabindex="-1">Response Status <a class="header-anchor" href="#response-status" aria-label="Permalink to &quot;Response Status&quot;">​</a></h3><p>Status code differences are clearly highlighted:</p><div class="language-diff vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">diff</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">- HTTP/1.1 200 OK</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+ HTTP/1.1 404 Not Found</span></span></code></pre></div><h3 id="timing-comparison" tabindex="-1">Timing Comparison <a class="header-anchor" href="#timing-comparison" aria-label="Permalink to &quot;Timing Comparison&quot;">​</a></h3><p>Timing data from both entries is shown side by side, making it easy to spot performance differences:</p><table tabindex="0"><thead><tr><th>Phase</th><th>Entry A</th><th>Entry B</th><th>Delta</th></tr></thead><tbody><tr><td>DNS</td><td>12 ms</td><td>15 ms</td><td>+3 ms</td></tr><tr><td>Connect</td><td>35 ms</td><td>34 ms</td><td>-1 ms</td></tr><tr><td>TLS</td><td>48 ms</td><td>50 ms</td><td>+2 ms</td></tr><tr><td>Send</td><td>1 ms</td><td>1 ms</td><td>0 ms</td></tr><tr><td>Wait (TTFB)</td><td>132 ms</td><td>890 ms</td><td><strong>+758 ms</strong></td></tr><tr><td>Receive</td><td>17 ms</td><td>45 ms</td><td>+28 ms</td></tr><tr><td><strong>Total</strong></td><td><strong>245 ms</strong></td><td><strong>1035 ms</strong></td><td><strong>+790 ms</strong></td></tr></tbody></table><p>Large timing differences are highlighted to draw your attention to performance regressions.</p><h2 id="visual-highlighting" tabindex="-1">Visual Highlighting <a class="header-anchor" href="#visual-highlighting" aria-label="Permalink to &quot;Visual Highlighting&quot;">​</a></h2><p>The comparison view uses consistent color coding throughout:</p><table tabindex="0"><thead><tr><th>Color</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Green background</strong></td><td>Content that was added (present in Entry B, absent in Entry A)</td></tr><tr><td><strong>Red background</strong></td><td>Content that was removed (present in Entry A, absent in Entry B)</td></tr><tr><td><strong>Yellow/Orange background</strong></td><td>Content that was modified (present in both, but values differ)</td></tr><tr><td><strong>No highlight</strong></td><td>Content that is identical in both entries</td></tr></tbody></table><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><h3 id="before-after-testing" tabindex="-1">Before/After Testing <a class="header-anchor" href="#before-after-testing" aria-label="Permalink to &quot;Before/After Testing&quot;">​</a></h3><p>The most common use case is comparing traffic before and after a change:</p><ol><li>Capture a request <strong>before</strong> making a code or configuration change</li><li>Make the change</li><li>Capture the same request <strong>after</strong> the change</li><li>Compare the two entries to verify only the expected differences appear</li></ol><details class="details custom-block"><summary>Example Workflow: Testing a Bug Fix</summary><ol><li>Capture the API response that contains the bug (e.g., incorrect calculation)</li><li>Deploy the fix</li><li>Re-capture the API response</li><li>Compare: verify the response body contains the corrected value and nothing else has changed</li></ol><div class="language-diff vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">diff</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &quot;orderId&quot;: &quot;ORD-123&quot;,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &quot;items&quot;: [...],</span></span>
<span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">-   &quot;total&quot;: 99.99,        // Bug: wrong total</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+   &quot;total&quot;: 109.99,       // Fixed: correct total</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &quot;currency&quot;: &quot;USD&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span></code></pre></div></details><h3 id="debugging-inconsistent-behavior" tabindex="-1">Debugging Inconsistent Behavior <a class="header-anchor" href="#debugging-inconsistent-behavior" aria-label="Permalink to &quot;Debugging Inconsistent Behavior&quot;">​</a></h3><p>When the same request returns different results at different times:</p><ol><li>Capture the request when it works correctly</li><li>Capture the request when it behaves incorrectly</li><li>Compare to identify what differs -- headers, body, timing, or status code</li></ol><h3 id="comparing-environments" tabindex="-1">Comparing Environments <a class="header-anchor" href="#comparing-environments" aria-label="Permalink to &quot;Comparing Environments&quot;">​</a></h3><p>Compare how the same request behaves in different environments:</p><ol><li>Send a request to the staging API (e.g., <code>staging-api.example.com</code>)</li><li>Send the same request to the production API (e.g., <code>api.example.com</code>)</li><li>Compare the responses to identify environment-specific differences</li></ol><h3 id="reviewing-replayed-requests" tabindex="-1">Reviewing Replayed Requests <a class="header-anchor" href="#reviewing-replayed-requests" aria-label="Permalink to &quot;Reviewing Replayed Requests&quot;">​</a></h3><p>After using <a href="./request-replay.html">Request Replay</a> to re-send a request:</p><ol><li>Select the original request and the replayed request</li><li>Compare them to see if the response has changed</li><li>This is effectively an automated regression test</li></ol><h3 id="investigating-authentication-differences" tabindex="-1">Investigating Authentication Differences <a class="header-anchor" href="#investigating-authentication-differences" aria-label="Permalink to &quot;Investigating Authentication Differences&quot;">​</a></h3><p>Compare requests from different authentication contexts:</p><ol><li>Capture a request made by User A</li><li>Capture the same endpoint called by User B</li><li>Compare to verify that role-based access control is working correctly (e.g., User A sees admin fields, User B does not)</li></ol><hr><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Request comparison is a read-only operation. It does not modify the original traffic entries. Both entries remain unchanged in the traffic list after comparison.</p></div>`,63)])])}const u=t(n,[["render",o]]);export{g as __pageData,u as default};
